const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const point = ee.Geometry.Point([-122.403124, 40.575441]);
  const dateStart = '2020-08-25';
  const dateEnd = '2020-08-26'; // Exclusive end date
  const thresholdMgM2 = 12;

  // 2. Data Acquisition & Check
  // MERRA-2 M2T1NXAER provides hourly Black Carbon Column Mass Density in kg/m^2
  let collection = ee.ImageCollection('NASA/GSFC/MERRA/slv/2.0')
    .filterDate(dateStart, dateEnd)
    .filterBounds(point)
    .select('BCCOLMASS');

  const collectionSize = collection.size().getInfo();
  if (collectionSize === 0) {
    console.log('Evidence: No MERRA-2 images found for the specified date and location.');
    console.log('A: No');
    return;
  }
  console.log(`Evidence: Found ${collectionSize} hourly images for 2020-08-25.`);

  // 3. Processing
  // The question asks "Was there...", implying if any point during the day exceeded the threshold.
  // We use a max() reducer to find the highest value for the day at the location.
  const dailyMaxImage = collection.max();

  // 4. Calculation
  const scale = 1000; // MERRA-2 resolution is ~50km, so 1km scale is safe.
  const dataDict = dailyMaxImage.reduceRegion({
    reducer: ee.Reducer.first().combine({
      reducer2: ee.Reducer.count(),
      sharedInputs: true
    }),
    geometry: point,
    scale: scale,
    maxPixels: 1e9
  });

  const bcValueKgM2 = dataDict.get('BCCOLMASS_first').getInfo();
  const pixelCount = dataDict.get('BCCOLMASS_count').getInfo();

  // 5. Validation & Final Answer
  if (pixelCount === 0) {
    console.log('Evidence: Pixel count is zero. The point of interest is likely over a no-data area (e.g., ocean).');
    console.log('C2');
    return;
  }

  if (bcValueKgM2 === null || bcValueKgM2 === undefined) {
    console.log('Evidence: Calculation resulted in a null value.');
    console.log('C3');
    return;
  }

  // Convert from kg/m^2 to mg/m^2 (1 kg = 1,000,000 mg)
  const bcValueMgM2 = bcValueKgM2 * 1e6;
  console.log(`Evidence: Max Black Carbon on 2020-08-25: ${bcValueMgM2.toFixed(4)} mg/m^2.`);
  console.log(`Evidence: Threshold: ${thresholdMgM2} mg/m^2.`);

  if (bcValueMgM2 > thresholdMgM2) {
    console.log('A');
  } else {
    console.log('B');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE().catch(err => {
    console.error('An error occurred during the analysis:');
    console.error(err);
    console.log('D');
});
